Object.assign(SNIP,{"l39syn": "template <typename T>\nclass Hop {                          // lớp mẫu: \"hộp chứa một giá trị kiểu T\"\n    T giaTri;\npublic:\n    Hop(T x) : giaTri(x) {}\n    T lay() const { return giaTri; }\n    void dat(T x) { giaTri = x; }\n};\n\nHop<int> a(5);                       // phải ghi kiểu: Hop<int> là một lớp cụ thể\nHop<string> b(\"xin chao\");           // Hop<string> là một lớp khác hẳn", "l39out": "template <typename K, typename V>\nclass Cap {\npublic:\n    K khoa;\n    V giaTri;\n    Cap(K k, V v);\n    void in() const;\n};\n\ntemplate <typename K, typename V>             // viết lại dòng template\nCap<K, V>::Cap(K k, V v) : khoa(k), giaTri(v) {}\n\ntemplate <typename K, typename V>\nvoid Cap<K, V>::in() const {                  // Cap<K, V>:: chứ không phải Cap::\n    cout << khoa << \": \" << giaTri << \"\\n\";\n}"});PRESET_NOTES["l39"]={"Ví dụ: Lớp mẫu Hop": "Ba đối số mẫu khác nhau sinh ba lớp: Hop<int> (4 byte), Hop<string> (32 byte), Hop<double> (8 byte). Mỗi lớp có bản riêng của hàm tạo, lay, dat; hàm nào không được gọi (như Hop<string>::dat) thì không được sinh.", "Ví dụ: Ngăn xếp tự viết": "NganXep<T> bọc một vector<T>: đẩy vào và lấy ra đều ở cuối. Phần tử vào sau ra trước (LIFO). Cùng một mã dùng cho int và string; bài 40 dùng std::stack có sẵn.", "Ví dụ: Hàm thành viên viết ngoài lớp": "Hai tham số mẫu K, V nên Cap<string, int> và Cap<int, double> là hai lớp. Mỗi định nghĩa ngoài lớp viết lại template <typename K, typename V> và tên đầy đủ Cap<K, V>::.", "Ví dụ: Tham số mẫu là hằng số": "N = 3 là hằng số nên T a[N] là mảng thành viên cố định. Mang<int, 3> chiếm 3 × 4 + 4 (biến n) = 16 byte; Mang<char, 10> chiếm 10 + 2 byte đệm + 4 = 16 byte. Đổi N là đổi sang lớp khác.", "Lỗi: Hai bản của một lớp mẫu là hai kiểu khác nhau": "int đổi được sang double, nhưng Hop<int> không đổi được sang Hop<double>: đó là hai lớp riêng biệt, không có quan hệ kế thừa hay hàm tạo chuyển đổi nào. Sửa: Hop<double> b(a.lay());", "Lỗi: Thiếu đối số mẫu": "Mang cần hai đối số mẫu (kiểu và kích thước) nhưng chỉ ghi một: wrong number of template arguments (1, should be 2). Sửa: Mang<int, 10> m;", "Ví dụ: Hàm mẫu nhận lớp mẫu": "moHop(a) suy ra T = int từ kiểu Hop<int> của đối số. gopHop trả về một Hop<T> mới; với string, + nối chuỗi nên được \"abcd\"."};EX_HINTS["l39"]=[["Gặp ngoặc mở: đẩy vào. Gặp ngoặc đóng: ngăn xếp phải không rỗng và đỉnh phải là ngoặc mở cùng loại.", "Hết chuỗi mà ngăn xếp còn phần tử thì vẫn chưa cân đối."], ["Không xóa phần tử đầu vector (chậm); chỉ tăng chỉ số dau. Hàng rỗng khi dau == a.size().", "ra() trả về a[dau] rồi tăng dau: return a[dau++];"], ["Đếm tổng số lần thêm (dem). Phần tử thứ i (đếm từ 0) nằm ở ô a[i % N].", "Các phần tử đang giữ là từ lần thêm thứ max(0, dem − N) tới dem − 1."]];
/* ===================== BÀI 39 · Lớp mẫu (class template) ===================== */
/* Bài 39 · Lớp mẫu (class template)
   Sinh bởi công cụ soạn bài: ví dụ cho trình mô phỏng (kèm hình động), bài tập chấm tự động.
   Trắc nghiệm ở quiz.json, gợi ý ở hints.json, lời giải ở solutions/ (nội dung bảo vệ). */
const P39=[{label:"Ví dụ: Lớp mẫu Hop",input:"",code:"#include <iostream>\n#include <string>\nusing namespace std;\n\ntemplate <typename T>\nclass Hop {\n    T giaTri;\npublic:\n    Hop(T x) : giaTri(x) {}\n    T lay() const {\n        return giaTri;\n    }\n    void dat(T x) {\n        giaTri = x;\n    }\n};\n\nint main() {\n    Hop<int> a(5);\n    Hop<string> b(\"xin chao\");\n    Hop<double> c(2.5);\n    a.dat(a.lay() * 2);\n    cout << a.lay() << \" | \" << b.lay() << \" | \" << c.lay() << \"\\n\";\n    cout << sizeof(a) << \" \" << sizeof(b) << \" \" << sizeof(c) << \"\\n\";\n    return 0;\n}",viz:[{type:"tmpl"},{type:"mem"}]},{label:"Ví dụ: Ngăn xếp tự viết",input:"",code:"#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\ntemplate <typename T>\nclass NganXep {\n    vector<T> a;\npublic:\n    void day(T x) {\n        a.push_back(x);\n    }\n    void lay() {\n        a.pop_back();\n    }\n    T dinh() const {\n        return a.back();\n    }\n    bool rong() const {\n        return a.empty();\n    }\n    int kichThuoc() const {\n        return a.size();\n    }\n};\n\nint main() {\n    NganXep<int> s;\n    for (int i = 1; i <= 4; i++) {\n        s.day(i * 10);\n    }\n    s.lay();\n    cout << s.dinh() << \" \" << s.kichThuoc() << \"\\n\";\n    NganXep<string> t;\n    t.day(\"mot\");\n    t.day(\"hai\");\n    while (!t.rong()) {\n        cout << t.dinh() << \" \";\n        t.lay();\n    }\n    cout << \"\\n\";\n    return 0;\n}",viz:[{type:"tmpl"},{type:"mem"}]},{label:"Ví dụ: Hàm thành viên viết ngoài lớp",input:"",code:"#include <iostream>\n#include <string>\nusing namespace std;\n\ntemplate <typename K, typename V>\nclass Cap {\npublic:\n    K khoa;\n    V giaTri;\n    Cap(K k, V v);\n    void in() const;\n};\n\ntemplate <typename K, typename V>\nCap<K, V>::Cap(K k, V v) : khoa(k), giaTri(v) {}\n\ntemplate <typename K, typename V>\nvoid Cap<K, V>::in() const {\n    cout << khoa << \": \" << giaTri << \"\\n\";\n}\n\nint main() {\n    Cap<string, int> tuoi(\"An\", 20);\n    Cap<int, double> diem(7, 8.5);\n    tuoi.in();\n    diem.in();\n    diem.giaTri += 0.5;\n    diem.in();\n    return 0;\n}",viz:[{type:"tmpl"},{type:"mem"}]},{label:"Ví dụ: Tham số mẫu là hằng số",input:"",code:"#include <iostream>\n#include <string>\nusing namespace std;\n\ntemplate <typename T, int N>\nclass Mang {\n    T a[N];\n    int n = 0;\npublic:\n    bool them(T x) {\n        if (n == N) return false;\n        a[n++] = x;\n        return true;\n    }\n    T operator[](int i) const {\n        return a[i];\n    }\n    int soLuong() const {\n        return n;\n    }\n    int sucChua() const {\n        return N;\n    }\n};\n\nint main() {\n    Mang<int, 3> m;\n    for (int i = 1; i <= 5; i++) {\n        if (!m.them(i * i)) cout << \"Day, bo \" << i * i << \"\\n\";\n    }\n    cout << m.soLuong() << \"/\" << m.sucChua() << \": \" << m[0] << \" \" << m[2] << \"\\n\";\n    cout << sizeof(Mang<int, 3>) << \" \" << sizeof(Mang<char, 10>) << \"\\n\";\n    return 0;\n}",viz:[{type:"tmpl"},{type:"mem"}]},{label:"Lỗi: Hai bản của một lớp mẫu là hai kiểu khác nhau",input:"",code:"#include <iostream>\n#include <string>\nusing namespace std;\n\ntemplate <typename T>\nclass Hop {\n    T giaTri;\npublic:\n    Hop(T x) : giaTri(x) {}\n    T lay() const {\n        return giaTri;\n    }\n};\n\nint main() {\n    Hop<int> a(1);\n    Hop<double> b = a;\n    cout << b.lay() << \"\\n\";\n    return 0;\n}"},{label:"Lỗi: Thiếu đối số mẫu",input:"",code:"#include <iostream>\n#include <string>\nusing namespace std;\n\ntemplate <typename T, int N>\nclass Mang {\n    T a[N];\npublic:\n    int sucChua() const {\n        return N;\n    }\n};\n\nint main() {\n    Mang<int> m;\n    cout << m.sucChua() << \"\\n\";\n    return 0;\n}"},{label:"Ví dụ: Hàm mẫu nhận lớp mẫu",input:"",code:"#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\ntemplate <typename T>\nclass Hop {\n    T giaTri;\npublic:\n    Hop(T x) : giaTri(x) {}\n    T lay() const {\n        return giaTri;\n    }\n};\n\ntemplate <typename T>\nvoid moHop(const Hop<T>& h) {\n    cout << \"Trong hop co: \" << h.lay() << \"\\n\";\n}\n\ntemplate <typename T>\nHop<T> gopHop(const Hop<T>& x, const Hop<T>& y) {\n    return Hop<T>(x.lay() + y.lay());\n}\n\nint main() {\n    Hop<int> a(3), b(4);\n    Hop<string> s(\"ab\"), t(\"cd\");\n    moHop(a);\n    moHop(gopHop(a, b));\n    moHop(gopHop(s, t));\n    return 0;\n}",viz:[{type:"tmpl"},{type:"mem"}]}];
const sim39=makeSim2(document.getElementById("sim-l39"),{id:"s39",presets:P39});
makeEx2(document.getElementById("ex-l39"),sim39,[{t:"Kiểm tra ngoặc với ngăn xếp mẫu",d:"Viết lớp mẫu <code>NganXep&lt;T&gt;<\/code> (dùng vector bên trong) có <code>day<\/code>, <code>lay<\/code>, <code>dinh<\/code>, <code>rong<\/code>. Dùng <code>NganXep&lt;char&gt;<\/code> kiểm tra một chuỗi gồm các ngoặc <code>()[]{}<\/code> có cân đối không. Nhập q rồi q chuỗi (không chứa dấu cách); in <code>YES<\/code> hoặc <code>NO<\/code> cho mỗi chuỗi.",tests:[{in:"4\n([]{})\n([)]\n((\n}",out:"YES\nNO\nNO\nNO"},{in:"2\n()\n{[()()]}[]",out:"YES\nYES"},{in:"1\n)(",out:"NO"}],start:"#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\n// viết template <typename T> class NganXep\n\nbool canDoi(const string& s) {\n    // dùng NganXep<char>\n    return false;\n}\n\nint main() {\n    int q;\n    cin >> q;\n    for (int i = 0; i < q; i++) {\n        string s;\n        cin >> s;\n        cout << (canDoi(s) ? \"YES\" : \"NO\") << \"\\n\";\n    }\n    return 0;\n}",need:/template\s*<\s*(typename|class)\s+\w+\s*>\s*class\s+NganXep[\s\S]*NganXep\s*<\s*char\s*>/,needMsg:"Hãy viết lớp mẫu NganXep và dùng NganXep<char>."},{t:"Hàng đợi mẫu",d:"Viết lớp mẫu <code>HangDoi&lt;T&gt;<\/code> (dùng vector và một chỉ số đầu hàng) có <code>vao(x)<\/code>, <code>ra()<\/code> trả về phần tử đầu và bỏ nó khỏi hàng, <code>rong()<\/code>, <code>soLuong()<\/code>. Mô phỏng quầy phục vụ: nhập q lệnh, mỗi lệnh là <code>vao ten<\/code> hoặc <code>ra<\/code>. Với <code>ra<\/code>: in <code>Phuc vu ten<\/code>, hoặc <code>Hang rong<\/code> nếu không còn ai. Cuối cùng in <code>Con lai: k<\/code>.",tests:[{in:"5\nvao An\nvao Binh\nra\nvao Chi\nra",out:"Phuc vu An\nPhuc vu Binh\nCon lai: 1"},{in:"2\nra\nvao Tu",out:"Hang rong\nCon lai: 1"},{in:"3\nvao A\nra\nra",out:"Phuc vu A\nHang rong\nCon lai: 0"}],start:"#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\n// viết template <typename T> class HangDoi\n\nint main() {\n    int q;\n    cin >> q;\n    // HangDoi<string> h;\n    for (int i = 0; i < q; i++) {\n        string lenh;\n        cin >> lenh;\n        // xử lý vao / ra\n    }\n    return 0;\n}",need:/template\s*<\s*(typename|class)\s+\w+\s*>\s*class\s+HangDoi[\s\S]*HangDoi\s*<\s*string\s*>/,needMsg:"Hãy viết lớp mẫu HangDoi và dùng HangDoi<string>."},{t:"Bộ đệm vòng",d:"Viết lớp mẫu <code>BoDem&lt;T, N&gt;<\/code> chỉ giữ N phần tử thêm vào gần nhất: mảng <code>T a[N]<\/code>, thêm phần tử thứ N + 1 thì ghi đè phần tử cũ nhất. Hàm <code>in()<\/code> in các phần tử đang giữ từ cũ tới mới, cách nhau một dấu cách (không giữ phần tử nào thì in <code>(rong)<\/code>). Nhập n từ rồi m số nguyên; dùng <code>BoDem&lt;string, 3&gt;<\/code> cho các từ và <code>BoDem&lt;int, 4&gt;<\/code> cho các số. In hai dòng.",tests:[{in:"5\na b c d e\n2\n7 8",out:"c d e\n7 8"},{in:"0\n6\n1 2 3 4 5 6",out:"(rong)\n3 4 5 6"},{in:"3\nx y z\n4\n9 9 9 1",out:"x y z\n9 9 9 1"}],start:"#include <iostream>\n#include <string>\nusing namespace std;\n\n// viết template <typename T, int N> class BoDem\n\nint main() {\n    int n;\n    cin >> n;\n    // BoDem<string, 3> chu;\n    for (int i = 0; i < n; i++) {\n        string s;\n        cin >> s;\n    }\n    int m;\n    cin >> m;\n    // BoDem<int, 4> so;\n    for (int i = 0; i < m; i++) {\n        int x;\n        cin >> x;\n    }\n    return 0;\n}",need:/template\s*<\s*(typename|class)\s+\w+\s*,\s*int\s+\w+\s*>\s*class\s+BoDem/,needMsg:"Hãy viết template <typename T, int N> class BoDem."}]);

makeQuiz("quiz39","score39",[{"q": "<code>Hop&lt;int&gt;<\/code> và <code>Hop&lt;double&gt;<\/code> có quan hệ gì?", "o": ["Hop<int> là lớp cha của Hop<double>", "Là hai lớp độc lập, sinh từ cùng một mẫu", "Là cùng một lớp", "Hop<double> tự đổi được sang Hop<int>"], "a": 1, "e": "Mỗi bộ đối số mẫu sinh một lớp riêng, không chuyển đổi qua lại được."}, {"q": "Cách tạo đối tượng đúng cho <code>template &lt;typename T&gt; class Hop<\/code> (hàm tạo nhận một T) là:", "o": ["Hop(int) h(5);", "Hop<int> h(5);", "Hop h<int>(5);", "template Hop<int> h(5);"], "a": 1, "e": "Ghi đối số mẫu ngay sau tên lớp mẫu."}, {"q": "Định nghĩa hàm <code>lay<\/code> của <code>Hop&lt;T&gt;<\/code> bên ngoài lớp viết thế nào?", "o": ["T Hop::lay() const { ... }", "template <typename T> T Hop<T>::lay() const { ... }", "T Hop<T>::lay() const { ... }", "template T Hop::lay() const { ... }"], "a": 1, "e": "Phải lặp lại dòng template và ghi Hop<T>::."}, {"q": "Với <code>template &lt;typename T, int N&gt; class Mang<\/code>, N là gì?", "o": ["Một biến được truyền lúc chạy", "Một hằng số biết lúc biên dịch, là một phần của kiểu", "Số phần tử hiện có", "Một kiểu dữ liệu"], "a": 1, "e": "Tham số mẫu kiểu số phải là hằng; Mang<int, 3> và Mang<int, 4> là hai lớp khác nhau."}]);

